def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    aisle_matrix = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and count the number of pairs that can be separated by adding an aisle in each position
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                aisle_matrix[i][j] += 1

    # Find the most effective positions for aisles, aiming to separate as many chatting pairs as possible
    row_indices = []
    col_indices = []
    for i in range(M):
        for j in range(N):
            if aisle_matrix[i][j] > 0:
                row_indices.append(i)
                col_indices.append(j)

    # Return the optimal row and column indices for the aisles
    return " ".join(str(i) for i in row_indices), " ".join(str(i) for i in col_indices)

def count_passing_ways(n: int, m: int) -> int:
    if n == 1 or m == 0:
        return 1
    if m == 1:
        return n
    return count_passing_ways(n - 1, m - 1) + count_passing_ways(n - 1, m)

def max_energy(beads):
    # Initialize a 2D array to store the maximum energy for each sub-sequence
    dp = [[0] * (len(beads) + 1) for _ in range(len(beads) + 1)]

    # Base case: the maximum energy for a sub-sequence of length 1 is the head value of the bead
    for i in range(len(beads)):
        dp[i][1] = beads[i]

    # Fill in the table
    for i in range(2, len(beads) + 1):
        for j in range(len(beads) - i + 1):
            dp[j][i] = max(dp[j][i - 1], dp[j + 1][i - 1] + beads[j] * beads[j + i - 1])

    # Return the maximum energy for the entire sequence
    return dp[0][len(beads)]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        elif i > 0:
            term += '+'
        if abs(coeff) != 1 or i == 0:
            term += str(abs(coeff))
        if i > 1:
            term += 'x^' + str(i)
        elif i == 1:
            term += 'x'
        terms.append(term)
    return ''.join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort the applicants based on their test scores in descending order
    applicants.sort(key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff as 150% of the planned number of recruits, rounded down
    cutoff = int(1.5 * m)

    # Create a list to store the qualified applicants
    qualified_applicants = []

    # Iterate through the applicants and add those with scores equal to or higher than the cutoff to the list
    for applicant in applicants:
        if applicant[1] >= cutoff:
            qualified_applicants.append(applicant)

    # Return the interview score cutoff and the list of qualified applicants
    return (cutoff, qualified_applicants)

def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        mapping[encoded[i]] = original[i]

    # Check if the mapping is valid
    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 1:
        return 1
    if n < x * k:
        return 0
    return sum(count_partitions(n - x, k - 1, x) for _ in range(x))

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
        return 1
    if n not in memo:
        memo[n] = 0
        for i in range(1, int(n/2) + 1):
            memo[n] += count_sequences(n-i, i, memo)
    return memo[n]

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // a
        if a == b:
            if is_coprime(a, b):
                count += 1
        else:
            if is_coprime(a, b):
                count += 2
    return count

def is_coprime(a: int, b: int) -> bool:
    return gcd(a, b) == 1

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ''
    root = postorder[-1]
    inorder_idx = inorder.index(root)
    left_inorder = inorder[:inorder_idx]
    left_postorder = postorder[:inorder_idx]
    right_inorder = inorder[inorder_idx+1:]
    right_postorder = postorder[inorder_idx:-1]
    return preorder_traversal(left_inorder, left_postorder) + root + preorder_traversal(right_inorder, right_postorder)

def find_min_n_greater_than_k(k: int) -> int:
    n = 1
    while True:
        harmonic_sum = sum(1 / i for i in range(1, n + 1))
        if harmonic_sum > k:
            return n
        n += 1

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

