def calculate_score(system: int, points: str) -> list:
    game_scores = []
    player_score = 0
    opponent_score = 0
    for point in points:
        if point == "W":
            player_score += 1
        else:
            opponent_score += 1
        if player_score == system:
            if opponent_score < player_score - 2:
                game_scores.append(f"{player_score}:{opponent_score}")
                player_score = 0
                opponent_score = 0
    return game_scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n-1-i) for i in range(n))

